import java.io.BufferedReader;
import java.io.InputStreamReader;

public class Main {
    public static void main(String[] args) throws Exception {
        String mensagem = new BufferedReader(new InputStreamReader(System.in)).readLine();

        int divertidos = 0;
        int chateados = 0;

        for (int i = 0; i + 2 < mensagem.length(); i++) {
            if (mensagem.charAt(i) == ':' && mensagem.charAt(i + 1) == '-') {
                if (mensagem.charAt(i + 2) == ')') {
                    divertidos++;
                } else if (mensagem.charAt(i + 2) == '(') {
                    chateados++;
                }
            }
        }

        if (divertidos == chateados) {
            System.out.println("neutro");
        } else if (divertidos > chateados) {
            System.out.println("divertido");
        } else {
            System.out.println("chateado");
        }
    }
}
